sible signs of cost pressure or decelerating momentum."}}	{"balanceSheet":{"id":183,"financialPeriodId":222,"targetCompanyId":45,"intangibleAssets":"295600","tangibleFixedAssets":"248900","freeholdProperty":null,"leaseholdProperty":null,"plantMachinery":null,"fixturesFittings":null,"motorVehicles":null,"computerEquipment":null,"stockInventory":null,"tradeDebtors":"378450","prepayments":null,"amountsOwedByDirectors":null,"amountsOwedByConnectedCompanies":null,"directorsCurrentAccount":null,"otherDebtors":null,"cashAtBank":"1189680","totalCurrentAssets":"1568130","tradeCreditors":null,"taxationSocialSecurity":null,"vatPayable":null,"corporationTaxDue":null,"bankLoansOverdraftCurrent":null,"hirePurchaseCurrent":null,"accruals":null,"amountsOwedToDirectors":null,"otherCreditors":"342580","totalCurrentLiabilities":"342580","bankLoansLongTerm":null,"hirePurchaseLongTerm":null,"deferredTaxation":null,"otherLongTermDebt":"0","totalLongTermLiabilities":"0","shareCapital":"100","retainedEarnings":"1769950","totalEquity":"1770050","debtorsList":null,"creditorsList":null,"fixedAssetsDetail":null,"sourceDocumentId":234,"createdAt":"2026-03-27T11:57:36.229Z","updatedAt":"2026-03-27T11:57:36.229Z"},"fixedAssets":{"id":15,"targetCompanyId":45,"reportDate":"2024-01-31","totalGrossBookValue":"472300","totalAccumulatedDepreciation":"217612","totalNetBookValue":"254688","propertyGrossValue":"0","propertyNetBookValue":"0","plantMachineryGrossValue":"0","plantMachineryNetBookValue":"0","vehiclesGrossValue":"24800","vehiclesNetBookValue":"18600","itEquipmentGrossValue":"140400","itEquipmentNetBookValue":"60093","otherAssetsGrossValue":"307100","otherAssetsNetBookValue":"175995","refinanceableAssetsValue":"18600","fullyDepreciatedStillInUse":"0","assetItems":[{"description":"AI Platform License","category":"Software","purchase_date":"2021-02-03","cost":156000,"accumulated_depreciation":78000,"net_book_value":78000,"depreciation_rate":20,"depreciation_method":"Straight-line","location":null